import {
  getActiveCompanyId,
  getAuthUser,
  isTenantSwitchAllowed,
  resolveInitialActiveCompanyId,
  setActiveCompanyId,
} from '@linm-soft-org/linm-web-common-components';
import type { User } from '../models/User';

/** JWT-only tenant scope — must match BE CompanyAccessValidator (no Admin role bypass). */
function jwtTenantScope(user: Pick<User, 'canViewAllCompanies' | 'allowedCompanyIds' | 'companyId'>) {
  return {
    canViewAll: user.canViewAllCompanies === true,
    homeCompanyId: user.companyId,
    allowedCompanyIds: user.allowedCompanyIds,
  };
}

/**
 * Align `linm_active_company_id` (X-Company-Id) with JWT home + allowed_company_ids.
 * Call synchronously on app boot — before list pages fire API calls.
 */
export function reconcileActiveCompanyForUser(user: User | null | undefined): void {
  const scopedUser = user ?? getAuthUser();
  if (!scopedUser?.companyId) return;

  const { canViewAll, homeCompanyId, allowedCompanyIds } = jwtTenantScope(scopedUser);
  const homeCode = scopedUser.companyId;
  const active = getActiveCompanyId();

  if (active && !isTenantSwitchAllowed(active, canViewAll, allowedCompanyIds, homeCode)) {
    setActiveCompanyId(homeCode);
    return;
  }

  const initial = resolveInitialActiveCompanyId(
    homeCode,
    allowedCompanyIds,
    canViewAll,
  );
  if (initial && initial !== active) {
    setActiveCompanyId(initial);
  }
}
