import {
  clearAuthTokens,
  getAuthUser,
  setActiveCompanyId,
  setAuthUser,
} from '@linm-soft-org/linm-web-common-components';
import { User, UserRole } from '../models/User';

/** Default tenant for standalone dev — company code (X-Company-Id), not Guid. */
export const STANDALONE_DEFAULT_COMPANY_CODE = 'UBNA';

export const STANDALONE_MOCK_USER: User = {
  id: '22222222-2222-2222-2222-222222222222',
  username: 'dev.standalone',
  email: 'dev@linm.local',
  firstName: 'Dev',
  lastName: 'Standalone',
  fullName: 'Dev Standalone',
  role: UserRole.Manager,
  departmentId: 'd3700023-bff0-0000-0000-000000000000',
  departmentName: 'Phòng KHTH',
  skills: [],
  isActive: true,
  package: 'Staff',
  companyId: STANDALONE_DEFAULT_COMPANY_CODE,
  allowedCompanyIds: [STANDALONE_DEFAULT_COMPANY_CODE],
  canViewAllCompanies: true,
  createdAt: new Date().toISOString(),
  updatedAt: new Date().toISOString(),
};

/** Seed auth for standalone — skips if real session exists unless force. */
export function seedStandaloneAuth(force = false): void {
  if (!force && getAuthUser()) return;
  // DevAuth BFF ignores JWT; omit tokens so refresh-token is not called on 401.
  clearAuthTokens();
  setAuthUser(STANDALONE_MOCK_USER);
  setActiveCompanyId(STANDALONE_DEFAULT_COMPANY_CODE);
}
